svg.script:
console.log("Scalio started");


const JSON_URL =
"https://raw.githubusercontent.com/CowGoMoo357/htmlgamesrepos/main/games.json";


const gamesLayer =
document.getElementById("games");


const categoryLayer =
document.getElementById("categories");


const status =
document.getElementById("status");



let games = [];

let currentGames = [];

let gameOffsetY = 0;





fetch(JSON_URL)

.then(response => response.json())

.then(data => {


    console.log(
        "Loaded games:",
        data.games.length
    );


    games = data.games;

    currentGames = games;


    status.remove();


    createCategories();


    displayGames(
        games
    );


})


.catch(error=>{


    status.textContent =
    "Games failed: " + error;


    console.error(error);


});







function createCategories(){


    const categories = [

        "All",

        ...new Set(
            games.map(
                game=>game.category
            )
        )

    ];



    categories.forEach(
    (category,index)=>{


        const ns =
        "http://www.w3.org/2000/svg";



        const y =
        260 + index * 55;



        let button =
        document.createElementNS(
            ns,
            "g"
        );



        let rect =
        document.createElementNS(
            ns,
            "rect"
        );


        rect.setAttribute(
            "x",
            "60"
        );


        rect.setAttribute(
            "y",
            y-30
        );


        rect.setAttribute(
            "width",
            "170"
        );


        rect.setAttribute(
            "height",
            "40"
        );


        rect.setAttribute(
            "rx",
            "20"
        );


        rect.setAttribute(
            "fill",
            "#ffffff15"
        );





        let text =
        document.createElementNS(
            ns,
            "text"
        );


        text.setAttribute(
            "x",
            "145"
        );


        text.setAttribute(
            "y",
            y
        );


        text.setAttribute(
            "fill",
            "white"
        );


        text.setAttribute(
            "text-anchor",
            "middle"
        );


        text.setAttribute(
            "font-size",
            "16"
        );


        text.textContent =
        category;



        button.appendChild(rect);

        button.appendChild(text);





        button.onclick = ()=>{


            gameOffsetY = 0;



            if(category === "All"){


                displayGames(
                    games
                );


            }

            else {


                displayGames(

                    games.filter(
                        game =>
                        game.category === category
                    )

                );


            }


        };



        categoryLayer.appendChild(
            button
        );


    });


}







function displayGames(list){


    currentGames = list;


    gamesLayer.replaceChildren();



    gamesLayer.setAttribute(

        "transform",

        `translate(0 ${gameOffsetY})`

    );



    list.forEach(
    (game,index)=>{


        const ns =
        "http://www.w3.org/2000/svg";



        let group =
        document.createElementNS(
            ns,
            "g"
        );



        let x =
        330 +
        (index % 4) * 210;



        let y =
        250 +
        Math.floor(index / 4) * 230;





        let card =
        document.createElementNS(
            ns,
            "rect"
        );


        card.setAttribute(
            "x",
            x
        );


        card.setAttribute(
            "y",
            y
        );


        card.setAttribute(
            "width",
            "190"
        );


        card.setAttribute(
            "height",
            "210"
        );


        card.setAttribute(
            "rx",
            "25"
        );


        card.setAttribute(
            "fill",
            "#ffffff15"
        );


        group.appendChild(
            card
        );





        let icon =
        document.createElementNS(
            ns,
            "image"
        );


        icon.setAttribute(
            "x",
            x+55
        );


        icon.setAttribute(
            "y",
            y+20
        );


        icon.setAttribute(
            "width",
            "80"
        );


        icon.setAttribute(
            "height",
            "80"
        );


        icon.setAttribute(
            "href",
            game.icon
        );


        group.appendChild(
            icon
        );





        let title =
        document.createElementNS(
            ns,
            "text"
        );


        title.setAttribute(
            "x",
            x+95
        );


        title.setAttribute(
            "y",
            y+135
        );


        title.setAttribute(
            "fill",
            "white"
        );


        title.setAttribute(
            "text-anchor",
            "middle"
        );


        title.setAttribute(
            "font-size",
            "18"
        );


        title.textContent =
        game.name;



        group.appendChild(
            title
        );





        let cat =
        document.createElementNS(
            ns,
            "text"
        );


        cat.setAttribute(
            "x",
            x+95
        );


        cat.setAttribute(
            "y",
            y+165
        );


        cat.setAttribute(
            "fill",
            "#aaa"
        );


        cat.setAttribute(
            "text-anchor",
            "middle"
        );


        cat.textContent =
        game.category;



        group.appendChild(
            cat
        );





        group.onclick = ()=>{

            launchGame(
                game
            );

        };



        gamesLayer.appendChild(
            group
        );


    });


}






function scrollGames(amount){


    gameOffsetY += amount;



    let maxScroll =
    -(Math.ceil(
        currentGames.length / 4
    ) * 230 - 520);



    if(gameOffsetY > 0)

        gameOffsetY = 0;



    if(gameOffsetY < maxScroll)

        gameOffsetY = maxScroll;




    gamesLayer.setAttribute(

        "transform",

        `translate(0 ${gameOffsetY})`

    );


}






document.documentElement.addEventListener(

"wheel",

(event)=>{


    event.preventDefault();


    scrollGames(
        -event.deltaY
    );


},

{
    passive:false
}

);




async function launchGame(game){


    console.log(
        "Launching:",
        game.name
    );



    const html = await fetch(
        game.url
    )
    .then(
        response => response.text()
    );



    const oldWindow =
    document.getElementById(
        "gameWindow"
    );


    if(oldWindow){

        oldWindow.remove();

    }




    const ns =
    "http://www.w3.org/2000/svg";



    const fo =
    document.createElementNS(
        ns,
        "foreignObject"
    );


    fo.setAttribute(
        "id",
        "gameWindow"
    );


    fo.setAttribute(
        "x",
        "300"
    );


    fo.setAttribute(
        "y",
        "120"
    );


    fo.setAttribute(
        "width",
        "850"
    );


    fo.setAttribute(
        "height",
        "550"
    );



    const div =
    document.createElementNS(
        "http://www.w3.org/1999/xhtml",
        "div"
    );


    div.style.width =
    "100%";


    div.style.height =
    "100%";


    div.style.background =
    "#000";



    div.innerHTML =
    html;



    fo.appendChild(
        div
    );


    document.documentElement.appendChild(
        fo
    );



    /*
       Re-run scripts inside games
    */

    div.querySelectorAll(
        "script"
    )
    .forEach(oldScript=>{


        const newScript =
        document.createElement(
            "script"
        );


        if(oldScript.src){

            newScript.src =
            oldScript.src;

        }

        else {

            newScript.textContent =
            oldScript.textContent;

        }


        oldScript.replaceWith(
            newScript
        );


    });


}
